    public void LoadYamlInput()
    {
        string yamlData = """
deviceCode: sample
userCode: sample
verificationUri: sample
expiresIn: 1
interval: 1

""";

        var instance = DeviceAuthorization.FromYaml(yamlData);

        Assert.NotNull(instance);
        Assert.Equal("sample", instance.DeviceCode);
        Assert.Equal("sample", instance.UserCode);
        Assert.Equal("sample", instance.VerificationUri);
        Assert.Equal(1, instance.ExpiresIn);
        Assert.Equal(1, instance.Interval);
    }

