    [Fact]
    public void RoundtripJson()
    {
        // Test that FromJson -> ToJson -> FromJson produces equivalent data
        string jsonData = """
{
  "deviceCode": "sample",
  "userCode": "sample",
  "verificationUri": "sample",
  "expiresIn": 1,
  "interval": 1
}
""";

        var original = DeviceAuthorization.FromJson(jsonData);
        Assert.NotNull(original);

        var json = original.ToJson();
        Assert.False(string.IsNullOrEmpty(json));

        var reloaded = DeviceAuthorization.FromJson(json);
        Assert.NotNull(reloaded);
        Assert.Equal("sample", reloaded.DeviceCode);
        Assert.Equal("sample", reloaded.UserCode);
        Assert.Equal("sample", reloaded.VerificationUri);
        Assert.Equal(1, reloaded.ExpiresIn);
        Assert.Equal(1, reloaded.Interval);
    }

